#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
pub enum FormattingOption {
    PRETTY_PRINT,
    PRINT_INPUT_DELIMITER,
    SINGLE_QUOTES,
}
impl FormattingOption {
    // port: CommandLineRunner.FormattingOption#valueOf
    pub fn value_of(value: &str) -> Option<Self> {
        match value {
            "PRETTY_PRINT" => Some(Self::PRETTY_PRINT),
            "PRINT_INPUT_DELIMITER" => Some(Self::PRINT_INPUT_DELIMITER),
            "SINGLE_QUOTES" => Some(Self::SINGLE_QUOTES),
            _ => None,
        }
    }
}
impl std::fmt::Display for FormattingOption {
    // port: Enum#toString
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{self:?}")
    }
}
