// port: OptionHandler#printDefaultValue
fn print_list<T: ToString>(values: &[T]) -> Option<String> {
    if values.is_empty() {
        None
    } else if values.len() == 1 {
        Some(values[0].to_string())
    } else {
        Some(format!(
            "[{}]",
            values
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join(",")
        ))
    }
}
// port: AbstractMap#toString
fn java_map_string(values: &IndexMap<String, Option<String>>) -> String {
    format!(
        "{{{}}}",
        values
            .iter()
            .map(|(k, v)| format!("{k}={}", v.as_deref().unwrap_or("null")))
            .collect::<Vec<_>>()
            .join(", ")
    )
}

pub struct BooleanOptionHandler<'a> {
    _parser: &'a CmdLineParser,
    _option: &'a NamedOptionDef,
}
impl<'a> BooleanOptionHandler<'a> {
    // port: CommandLineRunner.Flags.BooleanOptionHandler#BooleanOptionHandler
    pub fn new(parser: &'a CmdLineParser, option: &'a NamedOptionDef) -> Self {
        Self {
            _parser: parser,
            _option: option,
        }
    }
    // port: CommandLineRunner.Flags.BooleanOptionHandler#parseArguments
    pub fn parse_arguments(&self, params: &Parameters<'_>) -> (ParsedValue, usize) {
        match params
            .get_parameter(0)
            .ok()
            .map(str::to_ascii_lowercase)
            .as_deref()
        {
            Some("true" | "on" | "yes" | "1") => (ParsedValue::Boolean(true), 1),
            Some("false" | "off" | "no" | "0") => (ParsedValue::Boolean(false), 1),
            _ => (ParsedValue::Boolean(true), 0),
        }
    }
    // port: CommandLineRunner.Flags.BooleanOptionHandler#getDefaultMetaVariable
    pub fn get_default_meta_variable() -> Option<&'static str> {
        None
    }
}
pub struct MultiFlagSetter<'a, T> {
    proxy: crate::args4j::spi::setter::StringFieldSetter<'a>,
    flag: T,
    entries: &'a mut Vec<FlagEntry<T>>,
}
impl<'a, T: Clone> MultiFlagSetter<'a, T> {
    // port: CommandLineRunner.Flags.MultiFlagSetter#MultiFlagSetter
    pub fn new(
        proxy: crate::args4j::spi::setter::StringFieldSetter<'a>,
        flag: T,
        entries: &'a mut Vec<FlagEntry<T>>,
    ) -> Self {
        Self {
            proxy,
            flag,
            entries,
        }
    }
    // port: CommandLineRunner.Flags.MultiFlagSetter#isMultiValued
    pub fn is_multi_valued(&self) -> bool {
        self.proxy.is_multi_valued()
    }
    // port: CommandLineRunner.Flags.MultiFlagSetter#getType
    pub fn get_type(&self) -> std::any::TypeId {
        self.proxy.get_type()
    }
    // port: CommandLineRunner.Flags.MultiFlagSetter#addValue
    pub fn add_value(&mut self, value: String) {
        let normalized_value = if !value.is_empty()
            && matches!(value.as_bytes()[0], b'\'' | b'"')
            && value.as_bytes().last() == value.as_bytes().first()
        {
            let end = value.len() - 1;
            assert!(end >= 1);
            value[1..end].to_owned()
        } else {
            value
        };
        self.proxy.add_value(normalized_value.clone());
        self.entries
            .push(FlagEntry::new(self.flag.clone(), normalized_value));
    }
    // port: CommandLineRunner.Flags.MultiFlagSetter#asFieldSetter
    pub fn as_field_setter(&self) -> Option<&crate::args4j::spi::setter::StringFieldSetter<'_>> {
        self.proxy.as_field_setter()
    }
    // port: CommandLineRunner.Flags.MultiFlagSetter#asAnnotatedElement
    pub fn as_annotated_element(&self) -> &NamedOptionDef {
        self.proxy.as_annotated_element()
    }
}

